from sympy import Function, symbols, diff, exp, series, S

class softplus(Function):
    """softplus(x) = log(1 + exp(x))."""
    @classmethod
    def eval(cls, x):
        if x.is_zero:
            return S("log(2)")
        return None                      # stay unevaluated

    def fdiff(self, argindex=1):
        x = self.args[0]
        return 1 / (1 + exp(-x))         # the logistic sigmoid

    def _eval_is_positive(self):
        return self.args[0].is_extended_real

x = symbols("x", real=True)
print(softplus(0))                       # log(2)
print(diff(softplus(x**2), x))           # 2*x/(1 + exp(-x**2))
print(softplus(x).is_positive)           # True
print(series(softplus(x), x, 0, 3))      # log(2) + x/2 + x**2/8 + O(x**3)
